import { execSync } from 'child_process';

export interface FooterContext {
  gitBranch?: string;
  gitStatus?: string;
  sessionDuration?: string;
  cost?: number;
  tokenCount?: number;
  contextPercent?: number;
}

export function getGitInfo(): { branch: string; status: string } {
  try {
    const branch = execSync('git rev-parse --abbrev-ref HEAD', {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    }).trim();
    const status = execSync('git status --porcelain', {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    })
      .trim()
      .split('\n')
      .filter(Boolean).length;
    return { branch, status: `${status} files` };
  } catch {
    return { branch: '', status: '' };
  }
}

export function formatCost(cost: number): string {
  return cost === 0 ? '$0.00' : cost < 0.01 ? '<$0.01' : `\$${cost.toFixed(2)}`;
}

export function formatTokens(tokens: number): string {
  if (tokens < 1000) return tokens.toString();
  if (tokens < 1_000_000) return `${(tokens / 1000).toFixed(1)}k`;
  return `${(tokens / 1_000_000).toFixed(2)}M`;
}

export function formatSessionDuration(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m ${seconds}s`;
  } else if (minutes > 0) {
    return `${minutes}m ${seconds}s`;
  } else {
    return `${seconds}s`;
  }
}

interface Theme {
  fg: (name: string, text: string) => string;
  bold: (text: string) => string;
  dim: (text: string) => string;
}

export function renderFooter(
  context: FooterContext,
  theme: Theme
): string {
  const parts: string[] = [];

  if (context.gitBranch) {
    const gitInfo = getGitInfo();
    if (gitInfo.branch) {
      let gitStr = theme.fg('accent', gitInfo.branch);
      if (gitInfo.status && gitInfo.status !== '0 files') {
        gitStr += theme.dim(` (${gitInfo.status})`);
      }
      parts.push(gitStr);
    }
  }

  if (context.sessionDuration) {
    parts.push(theme.dim(context.sessionDuration));
  }

  if (context.cost !== undefined) {
    const costStr = theme.dim(formatCost(context.cost));
    if (costStr) {
      parts.push(costStr);
    }
  }

  if (context.tokenCount !== undefined) {
    parts.push(theme.dim(`${formatTokens(context.tokenCount)} tokens`));
  }

  let contextPercentStr = '';
  if (context.contextPercent !== undefined) {
    const contextPercentValue = context.contextPercent;
    const contextPercentDisplay = `${contextPercentValue.toFixed(1)}% ctx`;
    if (contextPercentValue > 80) {
      contextPercentStr = theme.fg('error', contextPercentDisplay);
    } else if (contextPercentValue > 70) {
      contextPercentStr = theme.fg('warning', contextPercentDisplay);
    } else {
      contextPercentStr = contextPercentDisplay;
    }
    if (contextPercentStr) {
      parts.push(contextPercentStr);
    }
  }

  if (parts.length === 0) {
    return '';
  }

  const separator = theme.dim('  ');
  return theme.dim('─ ' + parts.join(separator) + ' ─');
}

